fn at(v: &Vec[Str], index: Int) -> Option[Str] {
  return v.get(index);
}

fn swap(v: &mut Vec[Str], a: Int, b: Int) -> Unit {
  if a >= v.len() || b >= v.len() { return; }
  let temp = v[a];
  v[a] = v[b];
  v[b] = temp;
}

fn main() -> Int {
  var fruits = Vec[Str]();
  fruits.push("apple");
  fruits.push("banana");
  fruits.push("cherry");
  swap(&mut fruits, 0, 2);
  return fruits[0].len();
}
